import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import Stripe from "https://esm.sh/stripe@14?target=deno";

// ---- inlined from _shared/rateLimit.ts ----
interface RateLimitConfig {
  windowSeconds: number;
  maxRequests: number;
}

// Prefer the authenticated user's id when available (tighter, can't be
// evaded by rotating IPs); fall back to IP for endpoints with no reliable
// caller identity.
function clientIdentifier(req: Request, userId?: string | null): string {
  if (userId) return `user:${userId}`;
  const forwarded = req.headers.get("x-forwarded-for");
  const ip = forwarded ? forwarded.split(",")[0].trim() : "unknown";
  return `ip:${ip}`;
}

async function checkRateLimit(
  supabaseAdmin: ReturnType<typeof createClient>,
  bucket: string,
  identifier: string,
  config: RateLimitConfig
): Promise<boolean> {
  const { data, error } = await supabaseAdmin.rpc("check_rate_limit", {
    p_bucket_key: `${bucket}:${identifier}`,
    p_window_seconds: config.windowSeconds,
    p_max_requests: config.maxRequests,
  });

  // Fail open on infra errors - a broken rate limiter shouldn't take every
  // endpoint in the app down with it.
  if (error) {
    console.error(`Rate limit check failed for ${bucket}:`, error);
    return true;
  }

  return data === true;
}

function rateLimitResponse(corsHeaders: Record<string, string>): Response {
  return new Response(JSON.stringify({ error: "Too many requests. Please try again shortly." }), {
    status: 429,
    headers: { ...corsHeaders, "Content-Type": "application/json", "Retry-After": "60" },
  });
}
// ---- end of rateLimit ----

// ---- inlined from _shared/releasePayout.ts ----
type ReleaseResult =
  | { released: true; alreadyReleased?: boolean; transferId?: string }
  | { released: false; reason: "not_connected" | "transfer_failed" | "no_transaction"; error?: string };

// stripe_transfer_id has three shapes:
//   null                 - nothing sent yet
//   "pending:<uuid>"     - a transfer is being attempted with that uuid as its
//                          Stripe Idempotency-Key. Stripe returns the same
//                          result for the same key, so re-running after a
//                          crash or timeout can never create a second transfer,
//                          and can't skip the transfer the way a bare marker did.
//   "tr_..."             - a real Stripe transfer id; the money has moved.
const PENDING_PREFIX = "pending:";
const LEGACY_PENDING = "pending";

// Centralizes what happens when funds held in escrow for an application get
// released, regardless of which of the three triggers fired it (TikTok
// auto-confirm, a brand's manual release, or an ungated instant payment).
// Creates the actual Stripe Transfer to the creator's connected account,
// then flips applications.status - previously each trigger duplicated a
// DB-only status flip with no real money movement behind it.
async function releasePayoutForApplication(
  supabaseAdmin: ReturnType<typeof createClient>,
  applicationId: string
): Promise<ReleaseResult> {
  const { data: application, error: appError } = await supabaseAdmin
    .from("applications")
    .select("id, campaign_id, creator_id")
    .eq("id", applicationId)
    .single();
  if (appError || !application) {
    return { released: false, reason: "no_transaction", error: "Application not found" };
  }

  // Not filtered by transactions.status: the Stripe webhook flips that to
  // "completed" as soon as the card charge itself succeeds, well before
  // release happens - it means "charge succeeded", not "creator paid".
  // Filtering on it (as the old client-side release code did) would match
  // zero rows by the time release actually runs.
  const { data: transaction, error: txError } = await supabaseAdmin
    .from("transactions")
    .select("id, creator_payout, stripe_charge_id, stripe_transfer_id")
    .eq("campaign_id", application.campaign_id)
    .eq("creator_id", application.creator_id)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  if (txError || !transaction) {
    return { released: false, reason: "no_transaction", error: "No matching transaction found" };
  }

  let existingTransfer = transaction.stripe_transfer_id as string | null;

  if (existingTransfer === LEGACY_PENDING) {
    // Left behind by the old code, which had no idempotency key. A transfer
    // may or may not have gone out before it stopped, so ask Stripe instead
    // of guessing in either direction.
    const listRes = await fetch(
      `https://api.stripe.com/v1/transfers?transfer_group=${encodeURIComponent(`application_${applicationId}`)}&limit=10`,
      { headers: { "Authorization": `Bearer ${Deno.env.get("STRIPE_SECRET_KEY")}` } }
    );
    const list = await listRes.json();
    if (list.error) {
      return { released: false, reason: "transfer_failed", error: "Couldn't check Stripe for an earlier payout - try again shortly." };
    }
    const found = (list.data || []).find((t: { amount: number; reversed?: boolean }) =>
      t.amount === transaction.creator_payout && !t.reversed
    );
    if (found) {
      await supabaseAdmin.from("transactions").update({
        stripe_transfer_id: found.id,
        payout_released_at: new Date().toISOString(),
      }).eq("id", transaction.id);
      await supabaseAdmin.from("applications").update({ status: "paid" }).eq("id", applicationId);
      return { released: true, alreadyReleased: true, transferId: found.id };
    }
    // Stripe has no transfer for this deal, so nothing was paid. Clear the
    // legacy marker and fall through to a normal claim.
    await supabaseAdmin.from("transactions").update({ stripe_transfer_id: null })
      .eq("id", transaction.id).eq("stripe_transfer_id", LEGACY_PENDING);
    existingTransfer = null;
  }

  if (existingTransfer && !existingTransfer.startsWith(PENDING_PREFIX)) {
    // A real transfer already exists - just make sure the application agrees.
    await supabaseAdmin.from("applications").update({ status: "paid" }).eq("id", applicationId);
    return { released: true, alreadyReleased: true, transferId: existingTransfer };
  }

  if (transaction.creator_payout > 0) {
    const { data: account } = await supabaseAdmin
      .from("creator_stripe_accounts")
      .select("stripe_account_id, payouts_enabled")
      .eq("user_id", application.creator_id)
      .maybeSingle();

    if (!account || !account.payouts_enabled) {
      // Best-effort nudge - failure here shouldn't block reporting the
      // real reason release didn't happen.
      try {
        await supabaseAdmin.from("notifications").insert({
          user_id: application.creator_id,
          type: "payout_setup_needed",
          title: "Set up payouts to get paid",
          body: "A brand has released a payment to you, but you need to finish setting up payouts first.",
          data: { application_id: applicationId },
        });
      } catch (err) {
        console.error("Failed to insert payout-setup-needed notification:", err);
      }
      return { released: false, reason: "not_connected" };
    }

    if (!transaction.stripe_charge_id) {
      // The underlying charge's webhook hasn't landed yet (rare - webhooks
      // are near-instant relative to how release is triggered).
      return { released: false, reason: "transfer_failed", error: "Payment hasn't finished settling yet - try again shortly." };
    }

    // The idempotency key for this payout. A fresh claim mints a new one; a
    // row already stuck in "pending:" reuses its key, so the retry is
    // deduplicated by Stripe against whatever the earlier attempt did.
    let attemptKey: string;
    if (existingTransfer) {
      attemptKey = existingTransfer;
    } else {
      // Atomically claim this transaction. Only one concurrent caller can win
      // the null -> pending update; the loser backs off instead of racing.
      attemptKey = `${PENDING_PREFIX}${crypto.randomUUID()}`;
      const { data: claimed } = await supabaseAdmin
        .from("transactions")
        .update({ stripe_transfer_id: attemptKey })
        .eq("id", transaction.id)
        .is("stripe_transfer_id", null)
        .select("id")
        .maybeSingle();

      if (!claimed) {
        // Another trigger is mid-payout right now. Don't report success
        // before its transfer has actually landed.
        return { released: false, reason: "transfer_failed", error: "This payout is already being processed - try again shortly." };
      }
    }

    const params = new URLSearchParams({
      amount: String(transaction.creator_payout),
      currency: "gbp",
      destination: account.stripe_account_id,
      source_transaction: transaction.stripe_charge_id,
      transfer_group: `application_${applicationId}`,
    });

    // If this throws (network drop), the row stays "pending:<key>" on purpose:
    // the next attempt reuses the key and Stripe returns the original result
    // instead of sending the money twice.
    const transferRes = await fetch("https://api.stripe.com/v1/transfers", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${Deno.env.get("STRIPE_SECRET_KEY")}`,
        "Content-Type": "application/x-www-form-urlencoded",
        "Idempotency-Key": attemptKey,
      },
      body: params,
    });
    const transfer = await transferRes.json();

    if (!transfer.id) {
      console.error("Stripe transfer failed for application", applicationId, transfer);
      // Stripe answered with an error, so no money moved. Release the claim
      // so the next attempt gets a fresh key rather than a replayed error.
      await supabaseAdmin.from("transactions")
        .update({ stripe_transfer_id: null })
        .eq("id", transaction.id)
        .eq("stripe_transfer_id", attemptKey);
      return { released: false, reason: "transfer_failed", error: transfer.error?.message || "Stripe transfer failed" };
    }

    const { error: updateError } = await supabaseAdmin.from("transactions").update({
      stripe_transfer_id: transfer.id,
      payout_released_at: new Date().toISOString(),
    }).eq("id", transaction.id);
    if (updateError) console.error("Failed to record transfer id:", updateError);

    await supabaseAdmin.from("applications").update({ status: "paid" }).eq("id", applicationId);
    return { released: true, transferId: transfer.id };
  }

  // Nothing to transfer (e.g. a $0 deal) - just release.
  await supabaseAdmin.from("applications").update({ status: "paid" }).eq("id", applicationId);
  return { released: true };
}
// ---- end of releasePayout ----

const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") ?? "", {
  apiVersion: "2023-10-16",
  httpClient: Stripe.createFetchHttpClient(),
});

const webhookSecret = Deno.env.get("STRIPE_WEBHOOK_SECRET") ?? "";

serve(async (req) => {
  // Fail closed. With an empty secret the signature check below would still
  // "pass" for anyone who signs a fake event with an empty key (the Stripe
  // library accepts that), so a missing or mistyped secret has to stop every
  // event rather than let forged ones through. Real signing secrets always
  // start with whsec_.
  if (!webhookSecret.startsWith("whsec_")) {
    console.error("stripe-webhook: STRIPE_WEBHOOK_SECRET is missing or malformed - refusing every event");
    return new Response("Webhook is not configured", { status: 500 });
  }

  const signature = req.headers.get("stripe-signature");
  if (!signature) return new Response("Missing signature", { status: 400 });
  const body = await req.text();

  let event;
  try {
    // Raw body plus the signature header, checked against the signing secret.
    // Anything that wasn't signed by Stripe with that secret, was changed after
    // signing, or is older than 5 minutes is refused here, before it touches
    // the database.
    event = await stripe.webhooks.constructEventAsync(body, signature, webhookSecret);
  } catch (err) {
    console.error("stripe-webhook: signature verification failed:", err);
    return new Response("Invalid signature", { status: 400 });
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
  );

  // Signature is already verified above, so this only guards against
  // abnormal volume (retries/DoS), not spoofed callers - generous limit.
  const withinLimit = await checkRateLimit(supabase, "stripe-webhook", clientIdentifier(req), {
    windowSeconds: 60,
    maxRequests: 60,
  });
  if (!withinLimit) return new Response(JSON.stringify({ error: "Too many requests" }), { status: 429 });

  if (event.type === "payment_intent.succeeded") {
    const paymentIntent = event.data.object as Stripe.PaymentIntent;

    // latest_charge is captured so release-payout can later create a
    // Stripe Transfer tied to this specific charge's funds (source_transaction)
    // rather than the platform's general balance.
    const { data: tx, error } = await supabase
      .from("transactions")
      .update({ status: "completed", stripe_charge_id: paymentIntent.latest_charge as string })
      .eq("stripe_payment_intent_id", paymentIntent.id)
      .select("campaign_id, creator_id, payout_release_mode")
      .maybeSingle();

    if (error) {
      console.error("Failed to update transaction:", error);
      return new Response(JSON.stringify({ error: error.message }), { status: 500 });
    }

    // Only save the card as "reusable" once Stripe has actually confirmed the
    // charge went through - doing this here (not client-side) means a
    // declined/abandoned card never gets remembered as if it worked.
    const brandId = paymentIntent.metadata?.brand_id;
    if (brandId && paymentIntent.payment_method) {
      try {
        const pm = await stripe.paymentMethods.retrieve(paymentIntent.payment_method as string);
        await supabase.from("brand_profiles").update({
          stripe_payment_method_id: pm.id,
          card_last4: pm.card?.last4 || null,
          card_brand: pm.card?.brand || null,
        }).eq("id", brandId);
      } catch (err) {
        console.error("Failed to save reusable card for brand", brandId, err);
      }
    }

    // Safety net: the client normally flips the matching application to
    // "funded" itself right after the charge confirms, but if that update
    // never lands (dropped connection, closed tab), the application would
    // stay "accepted" - which still looks payable, risking a second real
    // charge for the same deal on retry. The webhook is the one thing
    // guaranteed to fire once Stripe confirms the charge, so it reconciles
    // this independently of whatever the client managed to do.
    if (tx) {
      await supabase
        .from("applications")
        .update({ status: "funded", payout_release_mode: tx.payout_release_mode || "tiktok_gated" })
        .eq("campaign_id", tx.campaign_id)
        .eq("creator_id", tx.creator_id)
        .not("status", "in", "(funded,paid,rejected,disputed)");
    }
  }

  if (event.type === "payment_intent.payment_failed") {
    const paymentIntent = event.data.object as Stripe.PaymentIntent;

    await supabase
      .from("transactions")
      .update({ status: "failed" })
      .eq("stripe_payment_intent_id", paymentIntent.id);
  }

  // A card chargeback (the brand's bank reversing the payment) happens entirely
  // outside the app. Record it so the deal stops looking healthy and an admin
  // sees it. We can't claw back a Transfer automatically, so if the creator
  // was already paid this is flagged for manual handling, not silently ignored.
  if (event.type === "charge.dispute.created") {
    const dispute = event.data.object as Stripe.Dispute;
    const paymentIntentId = typeof dispute.payment_intent === "string" ? dispute.payment_intent : dispute.payment_intent?.id;
    if (paymentIntentId) {
      const { data: tx } = await supabase
        .from("transactions")
        .update({ status: "disputed" })
        .eq("stripe_payment_intent_id", paymentIntentId)
        .select("campaign_id, creator_id, stripe_transfer_id")
        .maybeSingle();
      if (tx?.stripe_transfer_id) {
        console.error("CHARGEBACK ON A PAID-OUT DEAL - manual recovery needed", { paymentIntentId, disputeId: dispute.id });
      }
    }
  }

  // A refund issued from the Stripe dashboard (not from inside the app) would
  // otherwise leave the transaction and deal looking paid. Mirror it here.
  // Refunds issued by refundApplication already set these, so this is a no-op
  // for them.
  if (event.type === "charge.refunded") {
    const charge = event.data.object as Stripe.Charge;
    const paymentIntentId = typeof charge.payment_intent === "string" ? charge.payment_intent : charge.payment_intent?.id;
    if (paymentIntentId && charge.amount_refunded >= charge.amount) {
      const { data: tx } = await supabase
        .from("transactions")
        .update({ status: "refunded" })
        .eq("stripe_payment_intent_id", paymentIntentId)
        .select("campaign_id, creator_id, stripe_transfer_id")
        .maybeSingle();
      if (tx && tx.stripe_transfer_id) {
        console.error("REFUND ISSUED AFTER PAYOUT - creator was already paid, manual recovery needed", { paymentIntentId });
      } else if (tx) {
        await supabase
          .from("applications")
          .update({ status: "refunded" })
          .eq("campaign_id", tx.campaign_id)
          .eq("creator_id", tx.creator_id)
          .not("status", "in", "(paid)");
      }
    }
  }

  // Fires when a subscription actually ends - either the brand canceled
  // (cancel-subscription sets cancel_at_period_end, this fires once that
  // period is up) or Stripe gave up retrying a failed renewal charge. This
  // is the only place is_enterprise ever gets turned back off - verified
  // is deliberately left alone, since it can also come from the separate
  // admin verification_requests approval flow and a lapsed subscription
  // shouldn't silently strip a badge earned that way.
  if (event.type === "customer.subscription.deleted") {
    const subscription = event.data.object as Stripe.Subscription;
    await supabase
      .from("brand_profiles")
      .update({ is_enterprise: false, subscription_cancel_at_period_end: false })
      .eq("stripe_subscription_id", subscription.id);
  }

  // If Stripe's failed-payment setting is "mark as unpaid" rather than
  // "cancel", a lapsed subscription is never deleted and Enterprise would stay
  // on without being paid for. Treat a subscription that has become unpaid (or
  // otherwise dead) the same as a deleted one. (past_due is left alone: that
  // is Stripe still retrying the card.) Needs the endpoint to receive
  // customer.subscription.updated events in Stripe.
  if (event.type === "customer.subscription.updated") {
    const subscription = event.data.object as Stripe.Subscription;
    if (["unpaid", "canceled", "incomplete_expired"].includes(subscription.status)) {
      await supabase
        .from("brand_profiles")
        .update({ is_enterprise: false, subscription_cancel_at_period_end: false })
        .eq("stripe_subscription_id", subscription.id);
    }
  }

  // A creator's payout release can fail with "not_connected" if their
  // Stripe payout setup wasn't finished yet at the moment a post got
  // confirmed live or an instant payment landed - nothing previously
  // retried that once they actually finished setup, leaving them stuck
  // showing "payout pending" until the brand happened to click manual
  // release again. This picks it back up automatically.
  if (event.type === "account.updated") {
    const account = event.data.object as Stripe.Account;
    if (account.payouts_enabled) {
      const { data: creatorAccount } = await supabase
        .from("creator_stripe_accounts")
        .update({
          payouts_enabled: true,
          charges_enabled: !!account.charges_enabled,
          details_submitted: !!account.details_submitted,
          updated_at: new Date().toISOString(),
        })
        .eq("stripe_account_id", account.id)
        .select("user_id")
        .maybeSingle();

      if (creatorAccount) {
        const { data: pendingApps } = await supabase
          .from("applications")
          .select("id, payout_release_mode")
          .eq("creator_id", creatorAccount.user_id)
          .eq("status", "funded")
          .not("payout_release_mode", "is", null);

        for (const app of pendingApps || []) {
          // Money only ever lands once the deliverable is met - a creator's
          // payouts becoming enabled (or Stripe re-sending account.updated,
          // which it does often) is never itself a reason to release. Only
          // a post-gated deal whose required post is already confirmed live
          // is retried here; everything else waits for the brand's release,
          // a confirmed post, or the 5-day auto-release after upload.
          let eligible = false;
          if (app.payout_release_mode === "tiktok_gated") {
            const { data: post } = await supabase
              .from("campaign_posts")
              .select("id")
              .eq("application_id", app.id)
              .eq("posted_by_role", "creator")
              .eq("status", "published")
              .maybeSingle();
            eligible = !!post;
          }
          if (eligible) {
            try {
              await releasePayoutForApplication(supabase, app.id);
            } catch (err) {
              console.error("Auto-retry release failed for application", app.id, err);
            }
          }
        }
      }
    }
  }

  return new Response(JSON.stringify({ received: true }), { status: 200 });
});